     "tema": "Arma a serviço do tráfico (2026)",
     "assertiva": "Nos crimes de posse e de porte de arma de fogo, a pena é aumentada da metade se o crime for praticado em concurso com crime da Lei de Drogas ou se a arma assegurar o sucesso da mercancia.",
     "gabarito": "E",
