     "assertiva": "O crime de embriaguez ao volante só pode ser provado por exame de sangue ou etilômetro que indique a concentração mínima legal.",
     "gabarito": "E",
     "comentario": {
      "resumo": "Art. 306, § 2º: admite **teste de alcoolemia, exame clínico, perícia, vídeo, prova testemunhal** ou outros meios, com direito à contraprova; os sinais de alteração psicomotora bastam (§ 1º, II).",
      "lei": [
       {
        "lei": "L9503",
        "art": "306",
        "par": "",
        "inc": "",
        "rotulo": "CTB, art. 306, § 2º",
        "texto": "mediante teste de alcoolemia ou toxicológico, exame clínico, perícia, vídeo, prova testemunhal ou outros meios de prova em direito admitidos"
       }
      ],
      "pegadinha": "Exigir prova tarifada.",
      "palavras_chave": [
       "prova testemunhal",
       "art. 306"
      ],
      "correcao": {
       "erro": "Afirma que a embriaguez ao volante só pode ser provada por exame de sangue ou etilômetro.",
       "certo": "A embriaguez ao volante pode ser provada por teste de alcoolemia ou toxicológico, exame clínico, perícia, vídeo, prova testemunhal ou outros meios de prova em direito admitidos, assegurada a contraprova (art. 306, § 2º)."
      },
      "aprofundamento": "O crime de embriaguez ao volante pode ser provado por dois caminhos: a concentração de álcool medida ou os **sinais de alteração da capacidade psicomotora**. O segundo caminho existe porque o condutor não é obrigado a soprar o etilômetro nem a fazer exame de sangue, já que ninguém é obrigado a produzir prova contra si.\n\nPor isso a lei admite exame clínico, perícia, vídeo, prova testemunhal e outros meios em direito admitidos, garantida a contraprova. O policial que descreve fala arrastada, odor etílico e desequilíbrio produz prova válida.\n\nA banca impõe prova tarifada. O sistema é de livre convencimento motivado.",
      "memorize": "Embriaguez ao volante: qualquer meio de prova admitido, inclusive testemunha e vídeo."
     }
