     "tema": "Direção sem habilitação",
     "assertiva": "Dirigir sem habilitação em via pública só é crime se gerar perigo de dano; sem ele, há apenas infração administrativa.",
     "gabarito": "C",
     "comentario": {
      "resumo": "Art. 309 e **Súmula 720/STF**: o CTB derrogou o art. 32 da LCP quanto à direção sem habilitação em vias terrestres.",
      "lei": [
       {
        "lei": "L9503",
        "art": "309",
        "par": "",
        "inc": "",
        "rotulo": "CTB, art. 309",
        "texto": "sem a devida Permissão para Dirigir ou Habilitação ou, ainda, se cassado o direito de dirigir, gerando perigo de dano"
       }
      ],
      "juris": [
       {
        "tribunal": "STF",
        "fonte": "Súmula 720/STF",
        "data": "24/09/2003",
        "texto": "O art. 309 do CTB, que reclama decorra do fato perigo de dano, derrogou o art. 32 da Lei das Contravenções Penais no tocante à direção sem habilitação em vias terrestres."
       }
      ],
      "palavras_chave": [
       "perigo de dano",
       "Súmula 720/STF"
      ],
      "aprofundamento": "Dirigir sem habilitação tinha dupla previsão: a contravenção da LCP e o crime do CTB. O STF entendeu que o CTB, ao exigir **perigo de dano**, derrogou a contravenção nas vias terrestres. A consequência é que a mera direção sem habilitação, sem gerar perigo, deixou de ser infração penal.\n\nResta a infração administrativa, com multa e retenção do veículo. Se a direção gerar perigo concreto, por exemplo, manobras arriscadas, há o crime do art. 309.\n\nA banca pode dizer que a conduta sem perigo continua contravenção. A Súmula 720/STF afasta isso.",
      "exemplo": "Rafael, sem CNH, dirige devagar e corretamente até a padaria: infração administrativa. Se avança sinais e quase atropela um pedestre, comete o crime do art. 309.",
      "memorize": "Direção sem habilitação: crime só com perigo de dano; sem ele, infração administrativa."
     }
