      "aprofundamento": "A saída temporária é benefício do regime semiaberto que pressupõe confiança: o preso sai sem vigilância direta. A Lei 14.843/2024 restringiu o instituto, vedando-o ao condenado por crime hediondo ou com violência ou grave ameaça contra pessoa, e a mesma vedação vale para o trabalho externo sem vigilância direta.\n\nA lei também reduziu as hipóteses de saída, que passaram a se limitar à frequência a curso supletivo, profissionalizante, ensino médio ou superior. As antigas saídas para visita à família deixaram de existir.\n\nA banca pode ressuscitar as hipóteses antigas ou permitir a saída para crimes violentos.",
