      "aprofundamento": "O servidor público que comete crime tributário ou contra as relações de consumo no exercício das funções trai o dever de proteger justamente o interesse que viola. Por isso a lei prevê causa de aumento de 1/3 até a metade.\n\nAs outras hipóteses do mesmo artigo seguem a lógica da gravidade: grave dano à coletividade e crimes ligados a bens essenciais à vida ou à saúde. Em todas, a pena sobe porque o impacto social é maior.\n\nA banca pode trocar a fração ou dizer que a condição de servidor é elementar do tipo.",
      "memorize": "Lei 8.137: servidor no exercício das funções, dano grave à coletividade ou bem essencial: +1/3 até a metade."
