      "aprofundamento": "A Lei 15.358/2026 mirou as estruturas que dominam territórios pelo terror: organizações criminosas ultraviolentas, grupos paramilitares e milícias privadas. Quando seus integrantes praticam os crimes dos arts. 33 a 37 no contexto de sua atuação, as penas são aplicadas **em dobro**.\n\nO par. ún. acrescenta que, havendo emprego de arma de fogo, aplica-se o concurso material, ou seja, as penas do crime de arma se somam. A lei afasta a ideia de que a arma seria absorvida pelo tráfico nesse contexto.\n\nPor ser novidade, a banca pode trocar a fração ou exigir que o crime seja praticado fora do contexto do grupo.",
