      "correcao": {
       "erro": "Afirma que a corrupção esportiva ativa é punida com detenção de 6 meses a 2 anos.",
       "certo": "Dar ou prometer vantagem para alterar ou falsear o resultado de competição esportiva é punido com reclusão, de 2 a 6 anos, e multa (art. 199 da Lei 14.597/2023)."
      },
      "aprofundamento": "A manipulação de resultados destrói o que dá valor ao esporte: a incerteza do resultado. Além disso, alimenta fraudes em apostas e envolve organizações criminosas. Por isso a lei pune com **reclusão**, de 2 a 6 anos, tanto quem corrompe quanto quem se deixa corromper.\n\nAs formas ativa, passiva e a fraude ao resultado têm a mesma pena, o que mostra que o legislador vê igual gravidade em todos os lados do esquema.\n\nA banca rebaixa a pena para detenção.",
