      "aprofundamento": "A Lei Geral do Esporte enfrenta duas formas de violência frequentes nos estádios: o racismo contra atletas e torcedores e a violência contra mulheres. A resposta é a pena aplicada **em dobro** nesses casos.\n\nA regra reflete a tendência de toda a legislação recente de agravar condutas discriminatórias. O dobro incide sobre as penas do crime de tumulto e violência em eventos esportivos.\n\nA banca pode trocar o dobro por aumento fracionário.",
