        "rotulo": "Lei 11.101/2005, art. 181, § 1º",
        "texto": "Os efeitos de que trata este artigo não são automáticos, devendo ser motivadamente declarados na sentença, e perdurarão até 5 (cinco) anos após a extinção da punibilidade"
