     "comentario": {
      "resumo": "Art. 91: é crime reter ou utilizar o cartão ou documento (detenção, de 6 meses a 2 anos), e a pena **aumenta de 1/3** se o autor é tutor ou curador.",
      "lei": [
       {
        "lei": "L13146",
        "art": "91",
        "par": "",
        "inc": "",
        "rotulo": "Lei 13.146/2015, art. 91",
        "texto": "Reter ou utilizar cartão magnético, qualquer meio eletrônico ou documento de pessoa com deficiência"
       }
      ],
      "pegadinha": "Criar excludente familiar.",
      "palavras_chave": [
       "cartão magnético"
      ],
      "correcao": {
       "erro": "Cria uma excludente de tipicidade para o familiar que administra os recursos.",
       "certo": "Reter ou utilizar cartão ou documento da pessoa com deficiência para obter vantagem indevida é crime do art. 91, inclusive por familiar, e a pena aumenta de 1/3 se o autor é tutor ou curador."
      },
      "aprofundamento": "O art. 91 protege a autonomia financeira da pessoa com deficiência: reter ou utilizar cartão magnético, meio eletrônico ou documento dela, para obter vantagem indevida para si ou para outrem, é crime, com detenção, de 6 meses a 2 anos, e multa.\n\nA lei não cria exceção para familiares. Ao contrário, quando o autor é tutor ou curador, a pena **aumenta de 1/3**, justamente porque a posição de administrador dos recursos agrava a violação. Administrar recursos não autoriza reter o cartão para proveito indevido.\n\nO que torna a conduta típica é a finalidade de vantagem indevida. A banca inventa uma excludente familiar que a lei não prevê.",
      "exemplo": "Uma sobrinha guarda o cartão do benefício do tio com deficiência e saca valores para despesas próprias. Responde pelo art. 91, sem excludente por ser parente.",
      "memorize": "Reter cartão de PcD: crime (art. 91); tutor ou curador = pena + 1/3."
     }
