     "gabarito": "C",
     "comentario": {
      "resumo": "**Art. 283, III**.",
      "lei": [
       {
        "lei": "L4737",
        "art": "283",
        "par": "",
        "inc": "",
        "rotulo": "Código Eleitoral, art. 283, III",
        "texto": "III - Os cidadãos que hajam sido nomeados para as mesas receptoras ou Juntas Apuradoras;"
       }
      ],
      "palavras_chave": [
       "mesas receptoras"
      ],
      "aprofundamento": "O art. 283 do Código Eleitoral amplia o conceito de membro e funcionário da Justiça Eleitoral para efeitos penais. Entre outros, o inciso III inclui os cidadãos nomeados para as **mesas receptoras ou juntas apuradoras**, como mesários e escrutinadores.\n\nO fundamento é que essas pessoas, embora não sejam servidores de carreira, exercem função pública essencial no dia da eleição. Se cometerem crime nessa função, respondem como funcionários; se forem vítimas, recebem a proteção correspondente.\n\nA lógica é semelhante à do conceito amplo de funcionário público do CP. A banca costuma afirmar que o mesário é mero particular.",
      "memorize": "Mesário e membro de junta apuradora: funcionários da Justiça Eleitoral para fins penais."
     }
