      "aprofundamento": "O § 1º do art. 302 do CTB aumenta de **1/3 à metade** a pena do homicídio culposo de trânsito em hipóteses de maior reprovabilidade. O inciso II alcança o crime praticado em faixa de pedestres ou na calçada.\n\nO fundamento é que esses são espaços de proteção do pedestre, onde ele tem a expectativa legítima de estar seguro. Atropelar ali revela desatenção mais grave ao dever de cuidado.\n\nA mesma fração e as mesmas hipóteses valem para a lesão corporal culposa de trânsito, por remissão do art. 303, § 1º. A banca costuma trocar a fração ou restringir o aumento ao homicídio.",
