      "lei": [
       {
        "lei": "L8176",
        "art": "1",
        "par": "",
        "inc": "",
        "rotulo": "Lei 8.176/1991, art. 1º, II",
        "texto": "II - usar gás liquefeito de petróleo para fins automotivos, em desacordo com as normas estabelecidas na forma da lei."
       }
      ],
      "palavras_chave": [
       "gás liquefeito de petróleo"
      ],
      "aprofundamento": "A Lei 8.176/1991 define crimes contra a ordem econômica ligados aos combustíveis. O inciso II do art. 1º, na redação da Lei 15.348/2026, pune usar **gás liquefeito de petróleo para fins automotivos**, em desacordo com as normas estabelecidas na forma da lei.\n\nO fundamento é duplo: o GLP é subsidiado e destinado ao uso doméstico, e seu uso em veículos desvia o produto da finalidade e gera risco de explosão, já que os veículos não são preparados para ele.\n\nO tipo é norma penal em branco: depende das normas regulatórias que dizem quando o uso é permitido.",
      "memorize": "Usar GLP em veículo, em desacordo com as normas: crime contra a ordem econômica (Lei 8.176/1991, art. 1º, II)."
