      "aprofundamento": "O § 1º do art. 2º da Lei 15.358/2026 aumenta de **2/3 ao dobro** a pena do domínio social estruturado em várias hipóteses. O inciso VIII alcança quem recruta, atrai, convida, induz, coage, permite ou consente que criança ou adolescente integre a organização ou execute seus atos.\n\nO fundamento é a proteção integral: as facções usam adolescentes como mão de obra descartável, aproveitando-se de sua vulnerabilidade e de sua responsabilização mais branda. A lei pune com rigor quem os explora.\n\nA lista de verbos é ampla e inclui condutas omissivas, como permitir e consentir. Basta tolerar a participação para incidir a majorante.",
