      "aprofundamento": "A aceitação da suspensão condicional do processo é uma escolha estratégica do acusado, que prefere cumprir condições a enfrentar o processo. Isso não significa que ele reconheça a legitimidade da acusação. A Súmula 667/STJ garante que a aceitação **não prejudica** a análise do pedido de trancamento da ação penal.\n\nO fundamento é que a suspensão impõe condições e mantém o acusado vinculado ao processo por todo o período de prova. Se a ação é manifestamente ilegítima, por atipicidade ou falta de justa causa, o acusado tem interesse em vê-la extinta, e não apenas suspensa.\n\nAssim, o habeas corpus para trancamento continua cabível.",
